#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;
struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {
    }
};

class Solution {
   public:
    ListNode* reverseList(ListNode* head) {
        return head;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<ListNode*> nodes;
    ListNode *head = nullptr, *tail = nullptr;
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        auto p = new ListNode(v);
        nodes.push_back(p);
        if (tail)
            tail->next = p;
        else
            head = p;
        tail = p;
    }
    auto p = Solution().reverseList(head);
    int k = 0;
    while (p && k < n) {
        if (k) cout << " ";
        cout << p->val;
        p = p->next;
        k++;
    }
    if (p || k != n) return 3;
    cout << "\n";
    for (auto q : nodes) delete q;
    return 0;
}

